import type { SVGProps } from "react";

// Bibliothèque d'icônes Solar (style Bold Duotone) — remplace Lucide dans toute l'app pour un
// rendu plus marqué/identifiable. Sources SVG officielles (iconify/icon-sets, collection Solar,
// licence MIT), embarquées statiquement — aucune génération IA, aucun appel réseau à l'exécution.
// Chaque icône garde le même nom que son équivalent Lucide d'origine pour ne changer que l'import
// dans les fichiers appelants.

type IconProps = { size?: number; className?: string } & Omit<SVGProps<SVGSVGElement>, "ref" | "width" | "height">;

function makeIcon(body: string, outlineBody?: string) {
  // strokeWidth accepté pour compatibilité avec les appelants historiques (héritage Lucide)
  // mais volontairement absorbé ici plutôt que transmis : ces icônes sont des formes pleines,
  // et un stroke-width hérité sur le <svg> racine se répercuterait sur les rares traits
  // explicites de certaines icônes (ex. Bot) sans qu'on le veuille.
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  return function SolarIcon({ size = 16, className, style, fill, strokeWidth, ...rest }: IconProps) {
    const html = fill === "none" && outlineBody ? outlineBody : body;
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        width={size}
        height={size}
        className={className}
        style={style}
        dangerouslySetInnerHTML={{ __html: html }}
        {...rest}
      />
    );
  };
}

